const {chromium}=require('playwright');const fs=require('fs');(async()=>{const b=await chromium.launch();fs.mkdirSync('th3',{recursive:true});
for(const f of fs.readdirSync('out3').filter(x=>x.includes('light'))){const w=f.includes('Tablet')?768:390;const p=await b.newPage({viewport:{width:w,height:800}});await p.goto('file://'+process.cwd()+'/out3/'+f);await p.waitForTimeout(150);const d=await p.evaluate(()=>[document.documentElement.scrollWidth,document.documentElement.scrollHeight]);console.log(f,d.join('x'));await p.screenshot({path:'th3/'+f.replace('.html','.png'),fullPage:true});await p.close()}await b.close()})();
